<script setup>
import { computed, nextTick, ref } from 'vue'
import { Plus, Search, X, Check, Users, ClipboardCheck, Pencil, ArrowRight, RefreshCw } from 'lucide-vue-next'
const props=defineProps({page:String,data:Object,api:Function})
const emit=defineEmits(['refresh','notify'])
const query=ref(''),kind=ref('all'),modal=ref(''),dialog=ref(),form=ref({}),selected=ref(null),busy=ref(false),error=ref('')
const partners=computed(()=>(props.data.partners||[]).filter(p=>(kind.value==='all'||p.kind===kind.value)&&`${p.name} ${p.contact} ${p.phone}`.toLowerCase().includes(query.value.toLowerCase())))
const counts=computed(()=>props.data.stocktakes||[])
const money=n=>new Intl.NumberFormat('zh-CN',{style:'currency',currency:'CNY'}).format(n/100)
const time=s=>new Date(s).toLocaleString('zh-CN',{hour12:false})
const delta=computed(()=>(form.value.lines||[]).reduce((n,l)=>n+Number(l.actual)-Number(l.expected),0))
async function open(type,item){modal.value=type;selected.value=item||null;error.value='';if(type==='partner')form.value=item?{...item}:{kind:'customer',name:'',contact:'',phone:'',address:'',note:''};if(type==='count')form.value={note:'',lines:[{productId:'',expected:0,actual:0}]};await nextTick();dialog.value.showModal()}
function close(){if(!busy.value){dialog.value.close();modal.value=''}}
function pick(l){const p=props.data.products.find(p=>p.id===l.productId);l.expected=p?.stock||0;l.actual=p?.stock||0}
async function save(){busy.value=true;error.value='';try{if(modal.value==='partner'){await props.api(selected.value?`partners/${selected.value.id}`:'partners',form.value,selected.value?'PATCH':'POST');emit('notify','往来单位档案已保存')}else{const r=await props.api('stocktakes',{note:form.value.note,lines:form.value.lines.map(l=>({...l,actual:Number(l.actual)}))});emit('notify',`${r.number} 盘点完成，库存与流水已更新`)}busy.value=false;close();emit('refresh')}catch(e){error.value=e.message}finally{busy.value=false}}
</script>
<template>
 <section class="business-page">
  <header class="business-heading"><div><span class="eyebrow">{{page==='partners'?'BUSINESS CONNECTIONS':'STOCK VERIFICATION'}}</span><h1>{{page==='partners'?'客户与供应商':'库存盘点'}}</h1><p>{{page==='partners'?'管理往来单位、联系信息与历史交易。':'核对账面与实物数量，记录差异和调整原因。'}}</p></div><button class="button primary" @click="open(page==='partners'?'partner':'count')"><Plus :size="16"/>{{page==='partners'?'新增往来单位':'新建盘点'}}</button></header>
  <div class="business-summary" v-if="page==='partners'"><article><Users :size="20"/><span>客户档案<b>{{(data.partners||[]).filter(p=>p.kind==='customer').length}}</b></span></article><article><Users :size="20"/><span>供应商档案<b>{{(data.partners||[]).filter(p=>p.kind==='supplier').length}}</b></span></article><article><Check :size="20"/><span>已完成业务单据<b>{{data.orders.length}}</b></span></article></div>
  <div class="data-panel" v-if="page==='partners'"><div class="toolbar"><label class="search"><Search :size="16"/><input v-model="query" aria-label="搜索往来单位" placeholder="搜索单位、联系人或电话"/></label><label class="select-wrap"><select v-model="kind" aria-label="往来类型"><option value="all">全部往来单位</option><option value="customer">客户</option><option value="supplier">供应商</option></select></label></div><div class="partner-grid"><article v-for="p in partners" :key="p.id" class="partner-card"><div class="partner-top"><span class="partner-avatar">{{p.name.slice(0,1)}}</span><span class="status">{{p.kind==='customer'?'客户':'供应商'}}</span><button class="icon-button" :aria-label="p.name+'编辑档案'" @click="open('partner',p)"><Pencil :size="15"/></button></div><h3>{{p.name}}</h3><p>{{p.contact||'未填写联系人'}} · {{p.phone||'未填写电话'}}</p><small>{{p.address||'未填写地址'}}</small><div class="partner-stats"><span>累计{{p.kind==='customer'?'销售':'采购'}}额<strong>{{money(p.total)}}</strong></span><button @click="open('partner-detail',p)">{{p.transactions.length}} 笔交易 <ArrowRight :size="14"/></button></div></article></div><div class="empty" v-if="!partners.length"><Users :size="32"/><h3>还没有匹配的往来单位</h3><p>建立档案后，开单时可直接选择单位名称。</p></div></div>
  <div class="data-panel" v-else><div class="toolbar"><h2>盘点记录</h2><span class="muted">{{counts.length}} 份已完成盘点单</span></div><div class="table-scroll"><table><thead><tr><th>盘点单号</th><th>盘点原因</th><th>商品数</th><th>差异数量</th><th>完成时间</th><th>操作</th></tr></thead><tbody><tr v-for="c in counts" :key="c.id"><td class="mono">{{c.number}}</td><td>{{c.note}}</td><td>{{c.lines.length}}</td><td>{{c.lines.reduce((n,l)=>n+l.delta,0)}} 件</td><td>{{time(c.createdAt)}}</td><td><button class="text-button" @click="open('count-detail',c)">查看详情</button></td></tr></tbody></table></div><div class="empty" v-if="!counts.length"><ClipboardCheck :size="34"/><h3>开始第一次库存盘点</h3><p>选择商品，输入实盘数量；确认前可查看差异。</p></div></div>
  <dialog ref="dialog" class="drawer wide" @cancel.prevent="close" @click="e=>{if(e.target===dialog)close()}"><div v-if="modal" class="drawer-inner"><header class="drawer-header"><div><span class="eyebrow">{{modal.includes('partner')?'PARTNER':'STOCKTAKE'}}</span><h2>{{modal==='partner'?(selected?'编辑往来单位':'新增往来单位'):modal==='count'?'新建库存盘点':modal==='partner-detail'?'往来单位详情':'盘点单详情'}}</h2></div><button class="icon-button" aria-label="关闭业务弹窗" :disabled="busy" @click="close"><X :size="20"/></button></header>
   <form v-if="modal==='partner'||modal==='count'" @submit.prevent="save"><div class="form-body"><template v-if="modal==='partner'"><p class="form-intro">单位名称和类型用于关联历史交易，创建后保持不变；联系资料可以随时更新。</p><div class="form-grid"><label>单位类型<select v-model="form.kind" :disabled="!!selected"><option value="customer">客户</option><option value="supplier">供应商</option></select></label><label>单位名称<input v-model="form.name" required maxlength="120" :disabled="!!selected"/></label><label>联系人<input v-model="form.contact" maxlength="50"/></label><label>联系电话<input v-model="form.phone" maxlength="40"/></label></div><label>联系地址<input v-model="form.address" maxlength="200"/></label><label>备注<textarea v-model="form.note" maxlength="500" rows="3"></textarea></label></template>
   <template v-else><p class="form-intro">请输入实际清点数量。确认后立即调整库存；若期间发生出入库，请刷新后重新盘点。</p><div class="line-title">盘点商品<button type="button" class="text-button" :disabled="form.lines.length>=100" @click="form.lines.push({productId:'',expected:0,actual:0})"><Plus :size="14"/>添加盘点行</button></div><div v-for="(l,i) in form.lines" :key="i" class="count-line"><label>盘点商品<select aria-label="盘点商品" v-model="l.productId" required @change="pick(l)"><option disabled value="">选择商品</option><option v-for="p in data.products" :key="p.id" :value="p.id">{{p.name}}</option></select></label><label>账面数量<input :value="l.expected" readonly/></label><label>实盘数量<input v-model.number="l.actual" required type="number" min="0" max="100000000000" step="1"/></label><div class="count-diff">差异<b :class="Number(l.actual)-l.expected<0?'text-amber':'text-blue'">{{Number(l.actual)-l.expected>0?'+':''}}{{Number(l.actual)-l.expected}}</b></div><button class="icon-button" type="button" :disabled="form.lines.length===1" @click="form.lines.splice(i,1)" aria-label="移除盘点行"><X :size="14"/></button></div><label>盘点原因<textarea v-model="form.note" required maxlength="500" rows="3" placeholder="例如：月末实物清点、发现库存差异"></textarea></label><div class="order-total"><span>预计库存调整</span><strong>{{delta>0?'+':''}}{{delta}} 件</strong></div></template><p class="form-error" v-if="error" role="alert">{{error}}</p></div><footer class="drawer-footer"><button class="button secondary" type="button" @click="close" :disabled="busy">取消</button><button class="button primary" type="submit" :disabled="busy"><RefreshCw v-if="busy" :size="15" class="spin"/><Check v-else :size="15"/>{{busy?'保存中…':modal==='partner'?'保存档案':'确认盘点'}}</button></footer></form>
   <div v-else class="form-body"><template v-if="modal==='partner-detail'"><h2>{{selected.name}}</h2><p class="form-intro">{{selected.contact}} {{selected.phone}}<br/>{{selected.address}}<br/>{{selected.note}}</p><div class="order-total"><span>累计交易金额</span><strong>{{money(selected.total)}}</strong></div><div class="detail-history"><div v-for="t in selected.transactions" :key="t.id"><span>{{t.number}}<small>{{time(t.createdAt)}}</small></span><b>{{money(t.total)}}</b></div></div><p v-if="!selected.transactions.length" class="muted">暂时没有已完成交易。</p></template><template v-else><h2>{{selected.number}}</h2><p class="form-intro">{{time(selected.createdAt)}}<br/>{{selected.note}}</p><div class="table-scroll"><table><thead><tr><th>商品</th><th>账面</th><th>实盘</th><th>差异</th></tr></thead><tbody><tr v-for="l in selected.lines" :key="l.id"><td>{{l.name}}</td><td>{{l.expected}}</td><td>{{l.actual}}</td><td>{{l.delta}}</td></tr></tbody></table></div></template></div>
  </div></dialog>
 </section>
</template>

